// Who prompt templates call the owner ({{owner}}, {{Owner}}, {{ownerFull}}): configuration, never a name in code.
// LINKNOTES_OWNER_NAME / LINKNOTES_OWNER_FULLNAME, default "the owner". Generated by the vendoring step in place of the
// upstream owner module.
const profile = (env) => ({ name: env.LINKNOTES_OWNER_NAME || 'the owner', fullName: env.LINKNOTES_OWNER_FULLNAME || env.LINKNOTES_OWNER_NAME || 'the owner' });
const cap = (s) => s[0].toUpperCase() + s.slice(1);
export const ownerName = ({ env = process.env } = {}) => profile(env).name;
export const ownerCap = (opts) => cap(ownerName(opts));
export function withOwner(text, { env = process.env } = {}) {
  const { name, fullName } = profile(env);
  return String(text).replaceAll('{{ownerFull}}', fullName).replaceAll('{{Owner}}', cap(name)).replaceAll('{{owner}}', name);
}
